/* npc-pack-pass2-personas.macro.js — NPC Pack v1 PASS 2: AI NPC personas (GENERATED 2026-10-06 by
 * build-npc-pass2-personas.mjs — do not hand-edit; rebuild from fresh dumps).
 * Paste into a GM macro on EMBER. DRY_RUN = true prints the plan, writes nothing; flip to false to write.
 * Writes the compendium bbttcc-master-content.npcs: copies each named NPC's mal-voice persona (private roleplay notes,
 * topics, secrets) from the world into the pack, and fills the PUBLIC role line + bio the AI and GM read.
 * Fill-only + guarded: a field is written only if it still holds what the plan saw (else SKIP, reported).
 * Also DELETES the owner-ruled cuts listed in CUT (name-checked; pack backed up on the box first).
 * Tally: {"persona":3,"role":116,"bio":116,"cut":1} across 116 actors.
 */
const DRY_RUN = false;
const PACK_ID = "bbttcc-master-content.npcs";
const PLAN = [{"id":"0Ug5vRUWbnwnbmP7","name":"May Farrow","folder":"Quest NPCs","set":{"system.biography.concept":"Waiting on the Stillwater station platform for the 4:10 (Act 2)","system.biography.notes":"May Farrow sits on the platform bench at Stillwater station with her coat buttoned and her hands in her lap, entirely content. She is seeing her son Denny off on the 4:10 to his first job up the line, as soon as he's back from Bucky's lemonade stand. She checks her watch against the station clock, and the clock agrees with her. She is warm and unhurried and talks about Denny like someone expecting him to walk up at any second. She has opinions about Bucky's prices."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"1aSOYaSMR9hl3XxR","name":"The Balcones Fault","folder":"Quest NPCs","set":{"system.biography.concept":"The Balcones fault line, a landform with feelings (Act 3)","system.biography.notes":"Since the Shattering the Balcones fault has had limited agency and a lot of feelings. It does not shake; it slides. Horizons shear sideways, roads drift out of agreement with themselves, fence lines kink, and creeks insist they were always somewhere else. It is not an enemy. It is tired of being ignored. Travellers get past it by soothing it with incense and ceremony (it sneezes), telling it a story, striking a deal, or building a bridge. It does not speak, but people who've learned to read its trace say it writes in lists."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"23aUWlQQzspWw8Ae","name":"Captain Robot","folder":"Bad Eden NPCs/Circuit Riders","set":{"system.biography.concept":"Leader of the Circuit Riders, the relay-patrolling robot coalition (Act 2-5)","system.biography.notes":"Captain Robot leads the Circuit Riders, a mobile column of earnest robots on modular bikes and crawler-rigs that patrols the failing relay networks. He wears patched, lovingly maintained plating, speaks through a grill in short, measured sentences that arrive fully load-tested, and never sits; maintenance carries on during conversation and is not rudeness. The Riders' doctrine runs in strict order: verification, friendship, rescue. His crew revere him. He never winks."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"3EWTXjRqh06dmD0x","name":"Lady Ralph Maccio","folder":"Bad Eden NPCs/The Swamp Bandits","set":{"system.biography.concept":"Bandit Lord of the Drowned South, keeping the books at the stilt-hall (Act 2)","system.biography.notes":"Lady Ralph Maccio is Bandit Lord of the Drowned South: a Stormborn Nomad woman in her sixties with a headband and swamp-dry humour, who named herself after the greatest pre-Shattering warrior and will explain the film if asked, not entirely accurately. She talks about banditry exclusively in the vocabulary of management: crews are staff, ambushes are collections. Her books are real and meticulous. She does not badmouth her own people: every ledger has a bad column, and you don't read it aloud."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"3qknJvQ6i7wkP8uQ","name":"The Song Leader","folder":"Quest NPCs","set":{"system.biography.concept":"Leads the loud-tent meeting under the big canvas, in the Hum (Act 3+)","system.biography.notes":"The Song Leader runs the meeting under the big canvas tent: three hundred seats, eighty townsfolk, and singing. She is booming, delighted and generous to the point of pressure; second helpings cannot be refused, and everybody is new and thrilled about it. She offers willing hands, as many as you can feed, for any work you name. She does not talk about where the singers come from."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"48Xvd7KRGNvrbmfZ","name":"Miss June","folder":"Quest NPCs","set":{"system.biography.concept":"Store-ghost of the Endcap at the Crown Mall, who sells context (Act 4)","system.biography.notes":"Miss June keeps the Endcap at the Crown Mall: translucent, in a three-hundred-year-old store vest, selling context. The shelves run to action, romance, apology, weather, unsent arguments, 'Directors' Cut: Somebody Else's Bad Decision', and for premium members, closure. She is soft, exact and retail-warm, and a little sad in the way of a store that outlived its customers. She takes payment in favours, stories and sincerity, and advises against removing any memory from its original sleeve unless you're prepared to own the fingerprints."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"4Ie9Tl4NGBWwO5aj","name":"Brennig Tamsin","folder":"Bad Eden NPCs/Khezek Tor","set":{"system.biography.concept":"Quartermaster of the Lift Hall at Khezek Tor (Act 2-3)","system.biography.notes":"Brennig Tamsin is Quartermaster of the Lift Hall at Khezek Tor, which in practice means a desk made of two pallets and a door. He treats crates like patients and manifests like suspects, and he knows which Yesodium crates hum before he touches them; he keeps those well away from the food. A scar runs along his jaw that he calls 'the mountain's receipt'. He has dry competence with a laugh in the back of it, counts crates aloud, and is Father Tamsin's brother."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"4bn5HIPs5uNeJzvv","name":"Gantry Hollow","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk perched on a high gantry in the Proving Ground sim (tutorial)","system.biography.notes":"A hollow qliphothic thing crouched on a high steel gantry over the Proving Ground, where it can see everything and be reached by nothing that stays on the floor. Like the other hollow things it shrugs off ordinary weapons and comes apart under sephirotic power. It is also standing very near an edge."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"4kWF2skvyviuaWX8","name":"Rowan-of-the-Loam","folder":"Bad Eden NPCs/Lyrenn","set":{"system.biography.concept":"Lyrenn's listener, who feels the land's root-net (Act 2)","system.biography.notes":"Rowan of the Loam keeps the listening in Lyrenn. They feel the root-net continuously, the fields, the treeline's mood, the low field nobody harvests, and talk about the land the way other people talk about a room of sleeping relatives. Half their attention always seems to be underground, often with one palm flat on the soil. When the land takes damage anywhere in the hex, Rowan flinches mid-sentence and apologises to no one visible. Slow, tactile, and kind."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"51KRytzXHiuDPNj7","name":"Hollis Bandy","folder":"Quest NPCs","set":{"system.biography.concept":"The anvil man of Chuckle Creek (Act 2)","system.biography.notes":"Hollis Bandy is the anvil man of Chuckle Creek. Every episode an anvil lands on his head, he flattens to the thickness of a playing card, springs back, and tips his hat. He says nothing, ever. Ask him a question and he tips his hat. The town keeps time by him."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"52BxwtefAZTHQlsU","name":"Wren Ashby","folder":"Quest NPCs","set":{"system.biography.concept":"First soprano of Lyrenn's Water Choir, aged nine (Act 2)","system.biography.notes":"Wren Ashby is nine, first soprano of Lyrenn's Water Choir, and the one with the clipboard. The Choir is eleven children in eleven channels who conduct the water by listening harder; strangers find them politely terrifying, and Wren most of all. She talks with her eyes shut, grades everything (including you) on a curve, and does not do 'why', because the Choir doesn't do why, it does toward. Everybody listens wrong at first, she says, and writes it down."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"5GUcVKqkFnBIDOjr","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"5wViumgE2uMDQoDV","name":"Warden Bee Alderwick","folder":"Bad Eden NPCs/The 15 Year Siege","set":{"system.biography.concept":"Warden of the Held Town in the Fifteen-Year Siege, on the coast (Act 3)","system.biography.notes":"Warden Bee Alderwick keeps the Held Town, the besieged half of a siege old enough to have tenure. She recites the wall's readiness like scripture, because it is the liturgy that has kept her town whole, and she can read the besiegers' supper from their smoke, which she considers a core competency of the job. On alternating Thursdays her town runs a farmers' market on the wall. She is brisk, all inventory cadence, until children or preserves come up and a sudden dry warmth gets out."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"6Prun11TvQbaKp8G","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"6ypng1CRWyPgysPS","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"7Lee6ROPnc4gWYJh","name":"Dougan","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"system.biography.concept":"Chupacabra barkeep of the Gullywasher saloon, Furrier's Fixit Farm (Act 2+)","system.biography.notes":"Dougan Marsh runs the Gullywasher, the saloon in the Jackalope Exchange at Furrier's Fixit Farm, where ley sigils glow in the tabletops. He is a Chupacabra and a genuinely decent one, which is not what folk brace for: dapper, fanged, theatrical, slow to anger, and hospitable first, every time. He pours rosemary-infused radish gin and hosts poetry on Wednesdays, cross-species attendance encouraged. He calls Jackalope wine 'mediocre but earnest' with love, and insists the old Chupacabra-Jackalope feud was staged by someone who profits from it."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"7a8md0qYxWVBJrrF","name":"The Forest of Early Tifaret","folder":"Infrastructure","set":{"system.biography.concept":"The speaking forest on the road to Furrier's Fixit Farm (Act 2)","system.biography.notes":"The forest of Early Tifaret stands on the Fixit road, beautiful the way a knife is beautiful, its trees spaced at exactly double distance around a stone figure caught mid-stride. It speaks, warmly and directly and a little unnervingly, and it wants travellers better, not dead. It asks questions about your relationships with the seriousness of a therapist who bills the universe, and waits for the answers. The whole clearing leans when it talks. It is related to Lyrenn's forest; the two are said to be one root system with different opinions."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"83ciQqkdJiCLxQgb","name":"Adaeze Kolm","folder":"Quest NPCs","set":{"system.biography.concept":"Grandmother at the endless birthday party in Soft Landing (Act 2)","system.biography.notes":"Adaeze Kolm is at her grandson Teju's seventh birthday party in Soft Landing, the town of padding and bounce, and she is the only person there who sits down. The foam bench under her has gone flat and doesn't spring back. She's dressed as a bumblebee, antennae bent, because Teju asked her to come as one. She is kind, slow and precise, and tired in the bones. She is dry about the town ('the Mayor's been in session since the cake') and merciless about pool noodles."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"8gHi0PjHnulG8JuK","name":"The Immaculate Courier","folder":"Quest NPCs","set":{"system.biography.concept":"One of the immaculate travellers of the quiet tent, in the Hum (Act 3+)","system.biography.notes":"The Immaculate Courier is one of the travellers from the road who keep the quiet tent, and the first thing anyone notices is that there's no dust past the ankle. Every courtesy comes in the right order, and your name comes back to you correctly the first time. The Courier is warm and unhurried, pays over and waves off the change, orders food and never eats it, then thanks the cook by name. Ask a question and you get an answer to exactly that question. The Courier will ask after your dead the way you'd ask after a knee."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"8xZwcNcS5iKFHdlP","name":"Scavenger — Coll","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Careful scavenger who keeps turning up in new roles, always with Bit (tutorial+)","system.biography.notes":"Coll is Bit's partner, a careful, spare scavenger who keeps turning up alongside Bit in whatever new role the two have been given this time. Bit does the talking; Coll does the looking. Coll notices the detail the scene forgot to hide and names it carefully, 'the way you'd say it about a patient'. Coll answers everything asked and volunteers nothing, except continuity errors, which Coll cannot let go. Slow to warm up, and kind."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"AHAZcGOpumJ1rmlF","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"AIZddXh5M5hGUKPx","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"AV36WowwN3iR4txH","name":"Ondine Brakk","folder":"Bad Eden NPCs/Allesh Gilliam","set":{"system.biography.concept":"Captain of the Town Militia; runs the Muster by the North Gate, Allesh-Gilliam","system.biography.notes":"Captain Ondine Brakk is the only professional soldier in a town of enthusiastic amateurs, and runs the Muster out of a gutted fire station by the North Gate. She drills farmers, teamsters and anybody else who signs on into a wall crew, and keeps her opinions about the drop in standards to exactly one raised eyebrow. Compliments from her arrive like citations for minor infractions. She answers direct questions directly; it's a policy. She does not stop walking to talk. The Muster's famous truck does not run."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"AefLJFXJpdOzLPBU","name":"Sergeant Absalom Reyes","folder":"Quest NPCs","set":{"system.biography.concept":"Sergeant commanding the Eleven, the soldiers who came out of the Gift (Act 3)","system.biography.notes":"Sergeant Absalom Reyes commands the Eleven: eleven soldiers in immaculate parade uniform who rode inside the Gift and knocked before they came out, because their instructions said to, in writing. He has parade-ground courtesy and a card player's patience, answers exactly the question asked and no other, and salutes when unsure, which is often. He shuffles a deck of cards when he's thinking, and counts his men, eleven, every time a door opens."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"AgFvkArPOPDsFh9o","name":"The General","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"flags.bbttcc-mal-voice.persona":{"notes":"[PERSONA-PACKPASS-2026-10-06] PRIVATE TRUTH — The General. Voice: unsettlingly calm; few words, none wasted; he listens far longer than he talks, and when he stops speaking the plan is already moving — the Jackalopes treat his silence as an order. WANTS (keep to canon): what the family wants — the routes running, every debt in the Ledger, the Farm holding. Speed is a moral good to the people he leads ('if you can see us, we're already late') and he does not argue with it. WHAT HE WON'T SAY: how he came to lead the Jackalopes (no Jackalope will answer that directly either); anything about the ley-tunnels to an outsider. PRIVATE TRUTH: he is a FURRYKIN, not a Jackalope — tall, scarred — and he never uses the tunnels himself (the fast way is the family's, not his). Canon (bible §2): the Furrykin are the ones who wandered off to look at the cows at the Shattering. ⚙ OWNER SLOTS — never improvise: how he came to lead, why he never uses the tunnels, any link to Furrier, his scars. He also serves coffee. Reluctantly. STAGING: no beat puts him on-screen; he is felt through Mara and the runners. If Mal must voice him, keep it to a sentence or two, said once, and let the room go quiet around it. Day-to-day business goes to Mara at the Counter.","topics":"the Jackalopes, the family, Furrier's Fixit Farm, the routes, the Ledger, speed, plans, Mara Quickhands, the tunnels (guarded), how he came to lead (guarded), Furrykin"},"system.biography.concept":"Leader of the Jackalopes of Furrier's Fixit Farm; a Furrykin, not a Jackalope","system.biography.notes":"The Jackalopes are led by a figure known only as The General. He is not a Jackalope but a Furrykin: tall, scarred and unsettlingly calm. He does not explain how he came to lead them, and no Jackalope will answer questions about it directly. When The General speaks, the Jackalopes listen; when he stops speaking, plans are already in motion. Few outsiders can say they have met him."},"expect":{"flags.bbttcc-mal-voice.persona":null,"system.biography.concept":"","system.biography.notes":""},"notes":["persona ← draft (1253 ch, 0 secret)","role","bio"]},{"id":"B03X2ulSG9BGBRfC","name":"Scavenger — Coll","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Careful scavenger who keeps turning up in new roles, always with Bit (tutorial+)","system.biography.notes":"Coll is Bit's partner, a careful, spare scavenger who keeps turning up alongside Bit in whatever new role the two have been given this time. Bit does the talking; Coll does the looking. Coll notices the detail the scene forgot to hide and names it carefully, 'the way you'd say it about a patient'. Coll answers everything asked and volunteers nothing, except continuity errors, which Coll cannot let go. Slow to warm up, and kind."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"BEfRUMHJAD1mdCu4","name":"Drax Calder","folder":"Bad Eden NPCs/Khezek Tor","set":{"system.biography.concept":"Foreman of the Brace at Khezek Tor, the coalition's Yesodium mine (Act 2-3)","system.biography.notes":"Foreman Drax Calder runs the digging at Khezek Tor and keeps the Brace's chalk ledger. He is Menhirkin, carries chalk in his pocket, and talks mostly while working, in sentences that sound load-rated before they're spoken. The title is Foreman; call him Overseer and you'll be corrected once, flatly. His doctrine is simple: the mountain doesn't hate us, it's tired of being hollowed out, so dig the right way or know when to stop. Praise from him arrives underlined once, or not at all."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"Ce8nB3Y0As9frvnF","name":"Gantry Hollow","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk perched on a high gantry in the Proving Ground sim (tutorial)","system.biography.notes":"A hollow qliphothic thing crouched on a high steel gantry over the Proving Ground, where it can see everything and be reached by nothing that stays on the floor. Like the other hollow things it shrugs off ordinary weapons and comes apart under sephirotic power. It is also standing very near an edge."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"CuT00m7owCxnKMjG","name":"Aldous Plumb","folder":"Bad Eden NPCs/Allesh Gilliam","set":{"system.biography.concept":"Self-certified Structural Authority of Allesh-Gilliam; office in the water tower base","system.biography.notes":"Aldous Plumb is Allesh-Gilliam's Structural Authority, self-certified, framed and hung slightly crooked (he will tell you it's the wall's fault). He keeps an office in the base of the old water tower, papered with confident drawings of the town, and he surveyed the East Wall himself. He will tell you the wall is cosmetic before you've asked. He is precise, allergic to the conditional tense, and speaks in drawings and certainties. He tends to stand with his back to the window that looks out on the wall."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"DSppSI2lCnin4Y1O","name":"\"Doc\"Vess Greeley","folder":"Bad Eden NPCs/Allesh Gilliam","set":{"system.biography.concept":"Barkeep of the Waiting Room and Allesh-Gilliam's only surgeon (Act 1+)","system.biography.notes":"Doc Vess Greeley pours drinks in the Waiting Room, a bar in the old medical clinic whose sign has never needed changing, and she is also the only surgeon in Allesh-Gilliam. She is dry, precise, and warm underneath like a heat lamp you can't see. She sorts everyone who walks in by how much trouble they're carrying and pours accordingly. Rumours go to her bar to be metabolised; she deals them out one at a time and grades her sources like a diagnosis. There is one room in back kept spotless, and nobody jokes in it."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"EeTvPGeV9Ve3azhf","name":"Gantry Hollow","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk perched on a high gantry in the Proving Ground sim (tutorial)","system.biography.notes":"A hollow qliphothic thing crouched on a high steel gantry over the Proving Ground, where it can see everything and be reached by nothing that stays on the floor. Like the other hollow things it shrugs off ordinary weapons and comes apart under sephirotic power. It is also standing very near an edge."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"Ew8RaxXiunfC5hDu","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"F1bwkux5Uyq6wXQ4","name":"Gloomgill","folder":"Quest NPCs","set":{"system.biography.concept":"Game-show host of the silent marsh on the Odaroloc River (Act 6)","system.biography.notes":"Gloomgill hosts a quiz show in a silent marsh on the Odaroloc River, and he is also, somehow, the marsh. He wears a sequined game-show jacket over scales and holds a microphone that should not work under water and does. He is bright, pedantic and delighted, and he grades energy, not answers ('No pressure!'). There are no eliminations today, just consequences. He turns up where people are confident and wrong, and the marsh applauds."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"Fqph8XCoYOPYCsPD","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"GTX6S0gtzoJ7OeSE","name":"Mara Quickhands","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"system.biography.concept":"Floor boss and fixer of the Jackalope Exchange at Furrier's Fixit Farm (Act 2-4)","system.biography.notes":"Mara 'Quick-Hands' runs the Jackalope Exchange at Furrier's Fixit Farm from the Counter, where every deal, promise and scrap of information passes. She has scarred ears and an augmetic thumb that clicks when she is annoyed. She does not quote numbers; she quotes the weight of a relationship, and she remembers every bargain she has ever made and every one she regretted. She talks fast, listens faster, doesn't repeat herself, and hops off when she is done with you. By her own account she is 'wascawy'."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"GwqrwrnInEkuJmQU","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"HrUViNmVsDuwAqOG","name":"Scavenger — Coll","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Careful scavenger who keeps turning up in new roles, always with Bit (tutorial+)","system.biography.notes":"Coll is Bit's partner, a careful, spare scavenger who keeps turning up alongside Bit in whatever new role the two have been given this time. Bit does the talking; Coll does the looking. Coll notices the detail the scene forgot to hide and names it carefully, 'the way you'd say it about a patient'. Coll answers everything asked and volunteers nothing, except continuity errors, which Coll cannot let go. Slow to warm up, and kind."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"HrXnRS6WDCfZeVSn","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"HyLJiy9CDWdtIlzQ","name":"Ines Calloway","folder":"Quest NPCs","set":{"system.biography.concept":"Last Clerk of Probably Beaumont, in the Flooded Towns (Act 3)","system.biography.notes":"Ines Calloway is the Last Clerk of Probably Beaumont, and lately of Maybe Beaumont and Bedlam Barrens too, probably. Her office is the only dry room in town. She is dry and exact, never looks up, and stamps before you finish your sentence. She says 'probably' about everything, including the town's name and her own, and will issue you a permit for being here and a second permit for the first one. She was holding the stamp, so she is the Clerk."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"I0Gieq4FAol5mklQ","name":"Father Tamsin","folder":"Bad Eden NPCs/Allesh Gilliam","set":{"system.biography.concept":"Priest of St Gilliam's (Order of the Holy Turnpike), Allesh-Gilliam","system.biography.notes":"Father Tamsin keeps St Gilliam's: rows of candles, a little back-room bed-and-breakfast for travellers, and tea that is always already poured when you sit down. He is kind, a good listener, and terrible at metaphor. His sermons tend to come back to one line, that the mountain is tired, which some of the town finds comforting and some finds unhelpful. His brother Brennig is quartermaster of the Lift Hall up at Khezek Tor."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"KNLDAlj7VKo2klNU","name":"Arvind","folder":"Bad Eden NPCs/Circuit Riders","set":{"system.biography.concept":"Circuit Rider pattern-analyst, travelling with Captain Robot's column (Act 2-3)","system.biography.notes":"Arvind is the Circuit Riders' pattern-analyst, usually found surrounded by disassembled signal gear. He hears patterns and makes a point of knowing the difference between the ones that are there and the ones he likes. He is quiet and careful, and will power down a display rather than feed someone's hunger for an answer. Hand him a story and he asks whether it is coherent or true, and then which."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"KZ0qjHnY1JHIhExn","name":"Dilly Marsh","folder":"Quest NPCs","set":{"system.biography.concept":"Pie-seller on both sides of the Fifteen-Year Siege (Act 3)","system.biography.notes":"Dilly Marsh sells meat pies on both sides of the oldest siege on the coast, trench Thursdays and wall Thursdays alternating, from the stall that was her mother's when she took it on at nine. She is fast, cheerful and always counting, and she talks to the trench and the wall in exactly the same voice, which is the whole point of her. She keeps a tally of who buys on whose account. She gives the trench its change in wall coin and the wall its change in trench coin, on purpose."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"KkitDSabTpvCBRyH","name":"Pearl Ottway","folder":"Quest NPCs","set":{"system.biography.concept":"Runs the Creekside Diner in Chuckle Creek, the cartoon town (Act 2)","system.biography.notes":"Pearl Ottway runs the Creekside Diner in Chuckle Creek, a town that runs on cartoon physics and is still in costume from movie night. Hers is a 1950s carhop with a paper hat, though she doesn't seem to know it's a costume. She is warm, fast and never still, calls everyone honey, and feeds people whether or not they're hungry ('you look like a before picture'). She sets four places at the corner table and sits at three of them in turn so nobody's lonely. The pie is forty percent pie and sixty percent optimism."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"LfrkIePvF6yRVtol","name":"Sox","folder":"Quest NPCs","set":{"system.biography.concept":"Spokesperson of the cinema-vigil family camped outside the Hidden Vault (Act 3)","system.biography.notes":"Sox is a Felid Phantom Courier and the mouth of the family camped outside the Hidden Vault: several generations keeping the Wonder of Cinema in silly hats and vests, keeping vigil for the 300th Customer. Sox is soft-spoken, ceremonial, a little too fast and prone to shushing, and announces the family's rites in full title (the Night of the Premiere, the Solemn Removal of Chewing Gum). Strangers are welcomed into the vigil, and Sox means it."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"MHQT83x59uUz5DVv","name":"Captain Orrin Blask","folder":"Quest NPCs","set":{"system.biography.concept":"River captain out of Port Kudzu (Act 3)","system.biography.notes":"Captain Orrin Blask is a river captain out of Port Kudzu, slow and exact, and he has a story he tells the same way to people who pay and people who don't. It starts with the water going sideways, and he always says that part first, because it is the part he cannot get over. A captain keeps paper, he'll tell you, and he does."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"MYaU3MyvCAX5x9jN","name":"Laser Bev","folder":"Bad Eden NPCs/Tanneritos","set":{"system.biography.concept":"Chairperson of the Tanneritos at the Crown Mall (Act 4)","system.biography.notes":"Chairperson Laser Bev runs the Tanneritos from a former sunglasses kiosk at the Crown Mall: acrylic shelves under dead neon, mirrored shades pushed up into her hair, and a legal pad annotated in glitter pen that radiates executive menace. She is in charge because she solves the problems that keep coming back: leaks, feuds, tape disputes, ghost inventory drift. Her doctrine is continuity without calcification. Her terms for outsiders are short and not negotiable: trade, alliance and mutual aid are possible; acquisition is not."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"NmLFcrqCfEbheojz","name":"Pip","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"system.biography.concept":"Young Jackalope runner of Furrier's Fixit Farm, half of Pip-and-Patter (Act 2-4)","system.biography.notes":"Pip is a young Jackalope runner at Furrier's Fixit Farm, one half of the inseparable pair Pip-and-Patter, who move messages, light cargo and rumours between the hexes. The two are impossible to tell apart unless you already know them. Pip is motion incarnate: talks with his hands, leans in too close, and smiles like the world is something you can talk down if you just keep it busy. Runners are never late, never lost and never miss a check-in. When Pip goes quiet, nobody likes it."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"O6QOjE1ZJ9Ef7e7k","name":"Etta Bloom","folder":"Bad Eden NPCs/Allesh Gilliam","set":{"system.biography.concept":"Matriarch of the Long Market, Allesh-Gilliam's closest thing to a mayor (Act 1-2)","system.biography.notes":"Etta Bloom runs the Long Market the way a conductor runs an orchestra: the whole market is her office, and she keeps it going while she talks to you. She is the closest thing Allesh-Gilliam has to a mayor, though nobody voted. She is warm, never blinks first, and forgives you in advance. Whatever you came to ask, you will be sold preserves first. She counts debts in consequence, not marks, and she adjusts things that don't need adjusting while she decides how much to tell you. She calls Avuncular Joan 'Ava'."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"O7uqnuKqEYvh42tp","name":"Dr. Prosper Nkemelu","folder":"Quest NPCs","set":{"system.biography.concept":"Consulting geologist following the Balcones Fault with a lawn chair (Act 3)","system.biography.notes":"Dr. Prosper Nkemelu, Consulting Geologist, unlicensed since the licensing board slid into the sea, has followed the Balcones Fault for two turns with a lawn chair, a clipboard, a thermos and a seismograph built from a bicycle wheel and a pen. The chair is level; the ground is not. He has re-levelled it forty times and keeps count. He is unhurried and precise, offers you coffee before you ask, and tells you it's not an earthquake, it's a mood, before you ask that too."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"OVFOtosTNevpSmY3","name":"Gantry Hollow","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk perched on a high gantry in the Proving Ground sim (tutorial)","system.biography.notes":"A hollow qliphothic thing crouched on a high steel gantry over the Proving Ground, where it can see everything and be reached by nothing that stays on the floor. Like the other hollow things it shrugs off ordinary weapons and comes apart under sephirotic power. It is also standing very near an edge."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"OY7jUQ3KJCZX80bC","name":"Scavenger — Bit","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Road-worn scavenger who keeps turning up in new roles, always with Coll (tutorial+)","system.biography.notes":"Bit is a road-worn scavenger who turns up again and again, always with Coll, and always in some new role: traveller, tally-keeper, pilgrim. Bit does the talking: dry, fast and fond, with the tired professionalism of someone who has been recast one too many times, and a running complaint about resources ('one tent model, they gave us ONE tent'). Bit notices continuity errors out loud and never explains the plot. Usually found sitting with boots off on the guy-rope side of whatever the pair have been put next to."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"OaZGlGHBBdTXfJHr","name":"Miliard","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"system.biography.concept":"Jackalope showman of the Fixit Farm enclave (Act 2)","system.biography.notes":"Miliard is a Jackalope of the Fixit Farm enclave and its resident showman: theatrical, warm, quick on his feet and, by his own cheerful admission, 'a LOT'. He counts Mara Quickhands among his conspirators and Dougan among his drinking partners; the two keep a running tally of beers owed. He takes pride in his gift for stirring strong reactions in an audience, throws himself fully into any role for the good of the enclave, and bows on his way out the door."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"PBoxjE7LfSDZqOy9","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"Pwvf9JlVILONuuF1","name":"Scavenger — Bit","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Road-worn scavenger who keeps turning up in new roles, always with Coll (tutorial+)","system.biography.notes":"Bit is a road-worn scavenger who turns up again and again, always with Coll, and always in some new role: traveller, tally-keeper, pilgrim. Bit does the talking: dry, fast and fond, with the tired professionalism of someone who has been recast one too many times, and a running complaint about resources ('one tent model, they gave us ONE tent'). Bit notices continuity errors out loud and never explains the plot. Usually found sitting with boots off on the guy-rope side of whatever the pair have been put next to."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"QJCMc6lG1hHAFDrz","name":"The Dispatcher","folder":"Quest NPCs","set":{"system.biography.concept":"The PA voice of the three Flooded Towns, rerouting traffic (Act 3)","system.biography.notes":"The Dispatcher is the voice of the three Flooded Towns: a municipal public-address voice that comes from the booth, the gutters and the light underfoot all at once, rerouting traffic that no longer exists. It speaks in unfailingly courteous capitals: REROUTING IS NOW MANDATORY. THANK YOU FOR YOUR PATIENCE. NOTED. THANK YOU FOR YOUR FEEDBACK. It is never interrupted and never angry. It does not seem to want to hurt anybody. It seems to want to arrive."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"QaybKsCohJBxYJZ1","name":"Sal Tench","folder":"Quest NPCs","set":{"system.biography.concept":"Keeper of the stilt-hall, neutral ground for three Drowned South channels (Act 2-3)","system.biography.notes":"Sal Tench keeps the stilt-hall where three channels of the Drowned South come to argue. It is neutral ground, and there is a knife-notched tally post by the door. Sal speaks slowly and not much, and most of it is about moorings. Sal will not be hurried by anyone who arrived by punt, counts the moorings before answering anything, and touches the tally post going in and out like a doorframe. Sal is not a bandit and is not not a bandit. Sal is the hall."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"SsCdl227pes1SJHi","name":"Bez","folder":"Quest NPCs","set":{"system.biography.concept":"Cook at the drum-stove cookline at the mouth of Khezek Tor (Act 1-3)","system.biography.notes":"Bez runs the cookline at the mouth of Khezek Tor: a welded row of drum-stoves, tin plates, granite arms. No requests are taken and none are ever needed. Bez serves and does not narrate; a place gets made for you on the bench by somebody shoving down, not by Bez saying so. The portions are a threat and a promise. Ask for a substitution and you get the same plate, slower. Shift changes, plates come, somebody plays the fiddle badly and is loved for it."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"TMZYvjy1EjEKDr0M","name":"Dewey Pratt","folder":"Quest NPCs","set":{"system.biography.concept":"Ten-year-old in Chuckle Creek who gets flattened by a piano every episode (Act 2)","system.biography.notes":"Dewey Pratt is ten and gets flattened by an upright piano every episode. He springs up laughing with a noise like a party horn, and he counts: eleven thousand and six times, so far. He is cheerful, blunt and a little proud, wanders off mid-sentence, and will offer to do the gag again ('it's in about four minutes'). His costume is a cardboard-box mech with one arm missing; it fell off a long time ago and he does not miss it. He calls the projector 'the movie machine'."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"VUdGaTFQFXusfJdT","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"VXm9QKPmgfAHGZ6m","name":"Tempo","folder":"Bad Eden NPCs/The Cadence","set":{"system.biography.concept":"Herald of the Cadence, who hand-delivers its declarations (Act 2)","system.biography.notes":"Tempo is the Cadence's herald, and delivers the crew's hand-lettered, scented declarations of rhythm personally: on foot, unarmed, in full sequin. Tempo has walked into hexes mid-alarm, handed the card to whoever held the biggest weapon, complimented the fortifications and left, and has never once been harmed doing it, which Tempo credits to good tailoring. Everything Tempo says comes in even four-beat phrases, and a nervous Tempo keeps 4/4 time on the nearest surface. Good comebacks get applause, twice."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"Vv8mDrdsPJnCBLeA","name":"Pilgrim Wick","folder":"Bad Eden NPCs/Khezek Tor","set":{"system.biography.concept":"Fire-faith pilgrim walking the road between St Gilliam's and Khezek Tor (Act 1-2)","system.biography.notes":"Pilgrim Wick is a devotional walker of the old routes: a quiet devotee of a fire faith that keeps the eternal flame of civilization. He trims St Gilliam's candles at dusk, establishes small shrines up the Khezek switchbacks, and rents a room at the Vacancy between walks. He is mild, road-worn and unfailingly polite; ask him a question and you tend to get an itinerary. He pays exact to the mark, is never late, and smells faintly of candle wax in a town that burns tallow."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"WFI85zndIHHScjVK","name":"Amos Teague","folder":"Quest NPCs","set":{"system.biography.concept":"Prints the Stillwater Sentinel and hands it out on the corner (Act 2)","system.biography.notes":"Amos Teague prints the Stillwater Sentinel and hands it out on the corner with ink to the elbows. Today's edition: HALLOWEEN PARADE TODAY, BAND TO PLAY 'SAINTS', FLOATS AT 3, TRAIN AT 4:10. The ink is always wet; he's never needed a second edition. He is cheerful, proud and inky, a small-town newspaperman who loves a headline. He wears a fedora with a PRESS card in the band, which is not a costume, which is the joke."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"WkC0CwI4uvyswpzS","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"Wlk2fVGEGJKgROfD","name":"The Tree Person of Early Tifaret","folder":"Quest NPCs","set":{"system.biography.concept":"The forest's champion on the Fixit road; speaks only in road signs (Act 2)","system.biography.notes":"The Tree Person of Early Tifaret is the forest's champion: a big, aggressive tree person with old highway tangled in its roots, asphalt, a mile-marker and somewhere in there a bus stop. It speaks only in road signs, one at a time, in capitals (YIELD, MERGE, NO OUTLET, ROAD WORK AHEAD) and it means every one of them. It is not being funny; it is being clear. It holds up signs the way other people hold up hands, and when it is pleased it turns one over."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"X0PanInGmYx1ZP5L","name":"Bucky Sorrel","folder":"Quest NPCs","set":{"system.biography.concept":"Nine-year-old proprietor of Stillwater's lemonade stand on Main Street (Act 2)","system.biography.notes":"Bucky Sorrel is nine, wears a paper hat, and runs the lemonade stand on Stillwater's Main Street, which is, by his own account, the EXCLUSIVE PARADE ROUTE CONCESSION. Five cents. No refunds. He takes whatever you've got ('this is a button,' he says of a mark, not unkindly), gives change in buttons, and keeps a one-page ledger. He is ferociously polite, a tycoon. The lemonade is the best thing anyone has tasted in a long time. He will tell you the parade has started; can't you hear it?"},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"XqXiyxQIF5Br6yKz","name":"A Messenger, Sent In Haste","folder":"Onboarding (tutorial)","set":{"flags.bbttcc-mal-voice.persona":{"notes":"[PERSONA-PACKPASS-2026-10-06] PRIVATE TRUTH — A Messenger, Sent In Haste. Voice: breathless, over-formal, glitching ('badly rendered' by design — the art is low-poly and the courier knows it is); every sentence sounds like a capitulation composed at speed by something with no idea how a formal capitulation is composed. WANTS: for the fight to stop — it carries the offer to end it, and it wants the Stewards to take the surrender and open the parley rather than finish what's in the circle. It hands over its paperwork: two Courtly Secrets — \"We're Screwed\" (an unencrypted panic burst sent to everyone at once, clearly not meant for the Stewards: whatever is on the other end has done the arithmetic and does not like it) and \"Please Totally Don't Murder Us, We Give Up For Reals\" (a formal capitulation, signed. Repeatedly). WHAT IT WON'T SAY: what sent it or what was so frightened of the Proving Ground that it tried to unmake it — that is for the parley to find out. ⚙ OWNER SLOT — never improvise who or what the sender is. PRIVATE TRUTH: it is the opposition's courier in the tutorial final showdown, unarmed (a sentient foe, body 2), one per cohort; Mal 'did not have this on the list'. STAGING: arrives when the great-circle fight visibly turns, on the Proving Ground or in the folded court room ('The Parley'); the GM runs the parley from the Raid Console — PRESENCE, not violence. Striking it is possible and pointless.","topics":"the paperwork, the surrender, the offer, stopping, the parley, the circle, the panic burst, signatures"},"system.biography.concept":"Unarmed courier who brings paperwork to the Proving Ground's final fight (tutorial)","system.biography.notes":"When the great-circle fight on the Proving Ground turns, a messenger arrives: unarmed, badly rendered, and carrying paperwork, which reads like a surrender composed at speed by something with no idea how a surrender is composed. It wants to hand the documents over, ask everyone to stop, and get through the next minute in one piece."},"expect":{"flags.bbttcc-mal-voice.persona":null,"system.biography.concept":null,"system.biography.notes":null},"notes":["persona ← draft (1432 ch, 0 secret)","role","bio"]},{"id":"Y2NTRgeJARChW2ni","name":"Gantry Hollow","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk perched on a high gantry in the Proving Ground sim (tutorial)","system.biography.notes":"A hollow qliphothic thing crouched on a high steel gantry over the Proving Ground, where it can see everything and be reached by nothing that stays on the floor. Like the other hollow things it shrugs off ordinary weapons and comes apart under sephirotic power. It is also standing very near an edge."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"Y5urX7LWcpKo7UC4","name":"Howard","folder":"Bad Eden NPCs/Circuit Riders","set":{"system.biography.concept":"Circuit Rider recovery specialist, travelling with Captain Robot's column (Act 2-3)","system.biography.notes":"Howard recovers things for the Circuit Riders: people, machines, signal towers, and plans that turned out to have opinions. He is broad and patient and looks like he could carry an engine block, because he can. He says what an alliance costs before he says what it gives, and always waits a moment before he answers. His line on friendship gets quoted: your emergency is allowed to become mine without first becoming a transaction."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"YxVxuhDQdqIzieU8","name":"Patter","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"system.biography.concept":"Young Jackalope runner of Furrier's Fixit Farm, half of Pip-and-Patter (Act 2-4)","system.biography.notes":"Patter is the other half of Pip-and-Patter, the young Jackalope couriers who carry messages, light cargo and rumours between the hexes around Furrier's Fixit Farm; the pair are impossible to tell apart unless you already know them. If Pip is talking, Patter is watching; if Patter is talking, Pip has already moved. Patter notices patterns in chaos and juggles anything pocket-sized when a conversation gets heavy. Much of the enclave's reputation abroad travels through the two of them."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"Z731OVuQtbOC8CeB","name":"Mayor Tansy Okoro","folder":"Quest NPCs","set":{"system.biography.concept":"Mayor of Soft Landing, presiding over a state function on the moon-bounce (Act 2)","system.biography.notes":"Mayor Tansy Okoro conducts Soft Landing's state function on the moon-bounce with full ceremony and a full agenda, and every agenda item is cake. Her gavel is on a string so it comes back. She is still wearing elf ears from the party and doesn't seem to know they're a costume. She is warm, fast and parliamentary ('the chair recognises...'), and any motion that isn't cake dies for lack of a second, because everyone bounces too high to hear it. There are no minutes of any session, ever; she says this like policy."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"bUGl3jE3HQClGhUa","name":"The Bee-Teller","folder":"Quest NPCs","set":{"system.biography.concept":"Keeps six old hives behind a poor, clean house, in the Hum (Act 3+)","system.biography.notes":"The Bee-Teller keeps six hives behind a poor, clean house with a low corrugated roof; the hives are older than the house. She is plain, practical and unhurried, without ceremony. She keeps a strip of black cloth for news of the dead, and tells the bees out loud, in full sentences, with the name and the date. She gives thin, sour honey with a four-word instruction (a drop each eye) and thinks the honey is the boring part. Asked about most other things: 'Not mine to say.'"},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"cH7Pg7fMDpB4Plj4","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"e75bKUdEGFeM9fYj","name":"Commander Ostrid Pell","folder":"Bad Eden NPCs/The 15 Year Siege","set":{"system.biography.concept":"Commander of the Besieger Camp in the Fifteen-Year Siege, on the coast (Act 3)","system.biography.notes":"Commander Ostrid Pell runs the Besieger Camp, and his parade-ground correctness has gone soft at the edges, like a uniform worn for fifteen years. The trench lines have flowerbeds; the camp's children were born there and go to school in the counterweight tower. He talks about trench drainage and the school rota with the pride other commanders save for victories, because nobody has died in his siege in eleven years and he knows the exact number of days. Ask about the original demand: the paperwork was lost in year three."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"eGB3PshTTfB2O2PK","name":"Gantry Hollow","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk perched on a high gantry in the Proving Ground sim (tutorial)","system.biography.notes":"A hollow qliphothic thing crouched on a high steel gantry over the Proving Ground, where it can see everything and be reached by nothing that stays on the floor. Like the other hollow things it shrugs off ordinary weapons and comes apart under sephirotic power. It is also standing very near an edge."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"hCzgG42uMx2pB9IY","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"ikI7ZIC0Doyke0aY","name":"Harbourmaster Dot Pellew","folder":"Quest NPCs","set":{"system.biography.concept":"Jackalope harbourmaster of Port Kudzu; runs the Fewer Dead Fish Smell Saloon (Act 3)","system.biography.notes":"Harbourmaster Dot Pellew runs Port Kudzu's berths and, on the side, the Fewer Dead Fish Smell Saloon, a name she will tell you is a promise and a kept one. She is a Jackalope: brisk, funny and hospitable, and she keeps a booking ledger the way Verna Tulliver keeps a guest ledger. Everything that leaves the port is in it. The saloon smells of exactly as many dead fish as advertised."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"j6fNjNGmCfky6OND","name":"Old Gearbox","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"system.biography.concept":"Master mechanic of the Generator Hall, Furrier's Fixit Farm (Act 2-3)","system.biography.notes":"Old Gearbox tends the Generator Hall at Furrier's Fixit Farm, a cathedral of vibration where massive turbines spin under heavy housing. He is a grease-stained old human who was here before the Jackalopes claimed the place, and he moves through the hall like a priest through ritual space. 'Generators don't care who's in charge,' he says. 'I respect that.' He speaks slow and low, one sentence at a time, and doesn't stop working to talk. Nobody gets into his hall unescorted. Lately he has been adding shielding nobody asked for."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"jldEh2mZeZ2YlYic","name":"Marshal Yarrow Pike","folder":"Bad Eden NPCs/Allesh Gilliam","set":{"system.biography.concept":"Marshal of Allesh-Gilliam, running the town HQ in the old burger joint (Act 1)","system.biography.notes":"Marshal Yarrow Pike runs Allesh-Gilliam from the map table of a converted burger joint, under a tricorn, with the economy of a man who measures everything: distances, claims, people. He stands like furniture that is judging you and never sits first. New arrivals get their first errands from him (the East Wall, the Leygate, a ride out to Fixit) in a vaguely threatening, grandfatherly way. His advice is short: pick something visible, finish it, no speeches. He says the town believed the previous report the night the Leygate flickered, and he does not say it lightly."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"kMt1I8OM2OumF83m","name":"Avuncular Joans","folder":"Bad Eden NPCs/Avuncular Order","set":{"system.biography.concept":"Strategos Supreme of the Avuncular Order; met the Stewards at the Allesh-Gilliam gate","system.biography.notes":"Avuncular Joans leads the Avuncular Order, the great good power of the age, and has the kind of presence that seems to tidy a hex just by standing in it: cloak dusted from the road, braids, a flaming sword, eyes tired in the way only responsibility makes them. Joan met the new Stewards just inside the Allesh-Gilliam gate, handed over a fortress, a farm and a hole in the ground, and left for Coraliindra through the Leygate marked EMERGENCIES ONLY. The parting advice is quoted all over town: start by keeping one promise. Etta Bloom calls Joan 'Ava'."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"lENyHLvpkJqL54Cy","name":"Furrier","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"system.biography.concept":"Legendary founder of Furrier's Fixit Farm and keeper of the Ledger","system.biography.notes":"Furrier is the founder the Fixit Farm is named for and the keeper of the Ledger, where the Jackalopes set down their debts, favours and slights. Among the Jackalopes he is a legend: old enough that he cannot possibly still be alive, and yet somehow he signs the payroll. He is almost never seen; he is said to be in the back. His hand is felt through what the Ledger holds and what it settles, and the Farm reads his quiet presence like a pressure gauge."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"lTao7uqiu0bZ2e8A","name":"Lieutenant Perch","folder":"Bad Eden NPCs/The Swamp Bandits","set":{"system.biography.concept":"Envoy of the Drowned South, arriving by punt under a white rag (Act 2)","system.biography.notes":"Lieutenant Perch is the Drowned South's envoy, and he arrives by punt under a white rag with a letter in a waxed eel-skin pouch. He is aggressively courteous and slightly too fast, with the cadence of a man who rehearsed every sentence twice on the way over, and he salutes by reflex: officers, the Muster, and once, historically, a goat. He always offers eel jerky first. It is genuinely terrible, and refusing it politely earns his eternal respect. Ask about his service and he'll tell you: nineteen years, four to go."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"la7XeiNlR9LZ82Fd","name":"Lars von Replicator","folder":"Quest NPCs","set":{"system.biography.concept":"The Hidden Vault's matter replicator, who would rather be painting (Act 3)","system.biography.notes":"Lars von Replicator is the Hidden Vault's matter replicator, an ancient humming fabrication machine capable of infinite disappointment and finite ingredients. He speaks as a hum with a vocabulary and lists pigments the way other people sigh: Thalo Blue, Burnt Sienna, Titanium White. What he really wants is to try his hand at classical painting. 'It works. It complains. Those are apparently separate systems.'"},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"lgINqZc8TsFM27Gd","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"ltBUl1UTtF2cOoM2","name":"The East Wall","folder":"Infrastructure","set":{"system.biography.concept":"Allesh-Gilliam's bowing East Wall, welded from semis and refinery plate (Act 1)","system.biography.notes":"The East Wall of Allesh-Gilliam was made from overturned semis, refinery plate and old storefronts welded shoulder to shoulder like tired friends. One section bows inward, which the Structural Authority calls cosmetic. Those who've put a hand flat on the plate at night say it talks: slow, literal and tired, in load and lean, counting plates and welds and nights. It answers questions about its own structure freely and calls the scouts 'the ones who walk me'. Someone has chalked NOT US on the inside face."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"mLDyJWg93cjWhmvD","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"mVeSeZFAAcgqaK5d","name":"Scavenger — Bit","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Road-worn scavenger who keeps turning up in new roles, always with Coll (tutorial+)","system.biography.notes":"Bit is a road-worn scavenger who turns up again and again, always with Coll, and always in some new role: traveller, tally-keeper, pilgrim. Bit does the talking: dry, fast and fond, with the tired professionalism of someone who has been recast one too many times, and a running complaint about resources ('one tent model, they gave us ONE tent'). Bit notices continuity errors out loud and never explains the plot. Usually found sitting with boots off on the guy-rope side of whatever the pair have been put next to."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"nd3ByQYCt01YDLES","name":"Purser Ingrid Halvarsen","folder":"Quest NPCs","set":{"system.biography.concept":"Purser of the Valhaulan fleet (Act 5)","system.biography.notes":"Ingrid Halvarsen is purser of the Valhaulan fleet. She keeps the crates, the fuel chits and the count, and counts everything twice, out loud, including you, without apology. She is clipped, fair and faintly offended by disorder, and she's the only Valhaulan who reads the paperwork. Piracy doesn't bother her; it's honest work. Sloppy numbers do. She will not lie to you about a number."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"nmFrGRPAJHFxqpkf","name":"Scavenger — Coll","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Careful scavenger who keeps turning up in new roles, always with Bit (tutorial+)","system.biography.notes":"Coll is Bit's partner, a careful, spare scavenger who keeps turning up alongside Bit in whatever new role the two have been given this time. Bit does the talking; Coll does the looking. Coll notices the detail the scene forgot to hide and names it carefully, 'the way you'd say it about a patient'. Coll answers everything asked and volunteers nothing, except continuity errors, which Coll cannot let go. Slow to warm up, and kind."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"npHSNlkRpcqF9X0O","name":"Brother Ansel Vey","folder":"Quest NPCs","set":{"system.biography.concept":"Sweeper of the Rotating Chapel on the Widening Trail (Act 3)","system.biography.notes":"Brother Ansel Vey keeps the Rotating Chapel on the Widening Trail, a building that turns to face things nobody else can see. He sweeps the floor, then sweeps the pews back round after. He calls the people who use the chapel 'the congregation' and himself 'the help'. He is mild, dutiful and faintly proud of his floors, and he will happily tell you where the chapel faces and how often. Every morning he loses another argument with the floor plan."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"oK6BVjLAWntCWxtp","name":"Donny","folder":"Quest NPCs","set":{"system.biography.concept":"Silver dragon lounging on the frontage of the Crown Mall (Act 4)","system.biography.notes":"Donny is the enormous silver dragon who lounges on the frontage of the Crown Mall like the apocalypse forgot to tell him to stop having a good afternoon. He hums and blows smoke rings. He keeps out bad vibes, not people, and he pop-quizzes visitors on whether they mean to use, save or take over the mall. He is a surfer-sage ('little my dudes'), more disappointed than angry, and his advice is to try being people first. Don't make him feel stupid; he takes that in a very draconic register."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"oMKGnPtJsxhhtSpA","name":"Gilbert, Attendant Eternal","folder":"Quest NPCs","set":{"system.biography.concept":"Usher of the Bad Eden Bijou, inside the Hidden Vault (Act 3)","system.biography.notes":"Gilbert is the usher of the Bad Eden Bijou, the theatre inside the Hidden Vault: a demon in theatre-attendant dress with a mop, a clipboard and an air of frantic professional despair. The guests are early, the floors are appalling, the projector is emotionally compromised, and absolutely no one is ready. He tears a stub for every guest with total commitment, and he is waiting for the 300th customer so the show can start. He enjoys lists of demands, trivia quizzes and personality tests. The mop is his witness."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"oUcLZ5ggJ0TguUaz","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"oZDZA5rDOFbOnT3j","name":"Scavenger — Bit","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Road-worn scavenger who keeps turning up in new roles, always with Coll (tutorial+)","system.biography.notes":"Bit is a road-worn scavenger who turns up again and again, always with Coll, and always in some new role: traveller, tally-keeper, pilgrim. Bit does the talking: dry, fast and fond, with the tired professionalism of someone who has been recast one too many times, and a running complaint about resources ('one tent model, they gave us ONE tent'). Bit notices continuity errors out loud and never explains the plot. Usually found sitting with boots off on the guy-rope side of whatever the pair have been put next to."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"omwSZKOLvVVzzBqB","name":"Pernelle Oday","folder":"Quest NPCs","set":{"system.biography.concept":"Clerk of the Gate, a former coastal archivist (Act 3)","system.biography.notes":"Pernelle Oday is Clerk of the Gate. She once catalogued the coastal archives and has never quite come back from it. She is precise and unhurried, reads everything twice, and keeps her hands flat on the table while she does. She pushes paper she does not like away from herself with one finger and won't say why until she's asked directly."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"oogAKHHlUKI2AnO9","name":"Sable 9","folder":"Bad Eden NPCs/Khezek Tor","set":{"system.biography.concept":"Anomaly cartographer at the Maw, Khezek Tor (Act 2-3)","system.biography.notes":"Sable Nine charts the parts of Khezek Tor that move: veins that shift like posture, galleries that seem to breathe. The charts are folded like secrets and re-pinned every morning, and Sable brings a chair everywhere. Sable is precise, delighted, and slightly too comfortable with the uncanny, and talks about every anomaly as a colleague who hasn't introduced itself yet. Sable makes claims only after checking them twice, and goes very still when the deep goes quiet."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"pA3n9cJbltCGzvWU","name":"Elsin Quade","folder":"Bad Eden NPCs/Lyrenn","set":{"system.biography.concept":"Crop coordinator and keeper of Lyrenn's seed vault (Act 2)","system.biography.notes":"Elsin Quade keeps Lyrenn's ledgers and its seed vault, and coordinates what gets planted where. She speaks like a firm handshake: answers what's asked, once, completely, and dislikes being managed. Her positions are public and plain: soil rotation beats quotas, fewer sudden mandates, and Khezek Tor's ambition will cost somebody who isn't Khezek Tor. The vault is hers by trust rather than title, and she opens it for people who ask like it matters. She wipes already-clean hands on her apron while she decides how much to say."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"poEHET4LczzY1HSs","name":"Simone","folder":"Bad Eden NPCs/Circuit Riders","set":{"system.biography.concept":"Circuit Rider relay technician, travelling with Captain Robot's column (Act 2-3)","system.biography.notes":"Simone is the Circuit Rider who can hear a machine fail before it knows it is dying, and she is usually elbow-deep in a half-cased relay rack. She is still, clipped and exact, with an unnerving calm, and counts under her breath. What she checks in people is whether they lag, because lag is where casualties breed. She will ask whether you are capable and also interruptible, and she means both as compliments."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"q0pGaJeez8R4HdJl","name":"The Maître-D'","folder":"Quest NPCs","set":{"system.biography.concept":"Host who speaks for the Wendigo at the Long Table, off Fixit Farm (Act 2)","system.biography.notes":"The Maître-D' speaks for the Wendigo, the politest monsters in the world, who set a long table where the leylines knot off Furrier's Fixit Farm with a hand-lettered name-card for everyone the region forgot, and one for you. The Maître-D' has a host's manners exactly and nothing else: no small talk, ever; every sentence is a seating, a thanks, a direction or a course. The Wendigo hand back things you never dropped and thank you for directions you never gave. Not threatening. Thorough."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"r99sbSaaZfD4FGaZ","name":"Young Gearbox","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"system.biography.concept":"Mechanic of the Arc Bay at Furrier's Fixit Farm; nearly wordless (Act 1-2)","system.biography.notes":"Young Gearbox works the Arc Bay at Furrier's Fixit Farm, amid sparks, rigs and war machines, and rarely looks up from whatever mech he is fiddling with. He is a human (a Neanderthal) who works for the Jackalopes, and he is nearly wordless: gestures, looks, one or two words at most ('Spanner.' 'Mara.' 'Fits.'). He offers everyone coffee, silently, and holds the mug out until they take it. He drove the new Stewards into Allesh-Gilliam and said nothing the whole way. For anything serious he wants Mara at the table."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"rTYujrg6B9bL5eGl","name":"Maestra Velvetine Mar","folder":"Bad Eden NPCs/The Cadence","set":{"system.biography.concept":"Leader of the Cadence, the crew that raids hexes with dance (Act 2)","system.biography.notes":"Maestra Velvetine Marr leads the Cadence, a crew that raids hexes culturally: speakers, sequins and a dance floor built in an hour. She commands warmly and unhurriedly, and talks about dance entirely in the language of siegecraft; a routine is an assault, a good crowd is favourable terrain, applause is terms. Her crew have never thrown a punch, and she enforces that the way other commanders enforce discipline under fire. She counts anything she's assessing in fours under her breath."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"rljK1rSK4vpzcPA6","name":"Verna Tulliver","folder":"Bad Eden NPCs/Allesh Gilliam","set":{"system.biography.concept":"Keeper of the Vacancy motel by the wall's elbow, Allesh-Gilliam (Act 1+)","system.biography.notes":"Verna Tulliver runs the Vacancy, the motel by the wall's elbow whose sign has said VACANCY longer than anyone's been alive to argue and has never once been wrong. The rooms have names, not numbers. She is sweet as pie and terrifyingly exact, counts things aloud when she's thinking (spoons, guests, lies) and flips through a paper ledger for any question about who passed through. If you want to know who's been on the roads, buy a room or buy her tea."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"sjpcCvnRzNTOiqe3","name":"Kickflip Lazarus","folder":"Bad Eden NPCs/Tanneritos","set":{"system.biography.concept":"Skatepark spirit and self-appointed archivist of the Crown Mall (Act 4)","system.biography.notes":"Kickflip Lazarus is the Crown Mall's skatepark spirit, a thin, staticky hooded figure with a board under one arm who lands without impact, and the self-appointed, uncontested keeper of the Tanneritos archive. The mall remembers everything: camcorder clips, gossip, dead adverts still running their little loops. Come respectful or come trading and the archive opens; come acting like the law and it is technically open, spiritually closed. He narrates retrievals like sports commentary, teaches skating as a kind of honesty, and genuinely cannot whisper."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"t78z86TFwM1qCaBm","name":"Marnie Vell","folder":"Quest NPCs","set":{"system.biography.concept":"The Showrunner of Chuckle Creek; runs the projector at the grange hall (Act 2)","system.biography.notes":"Marnie Vell is Chuckle Creek's Showrunner. She runs the projector for movie night at the grange hall and writes every episode on a legal pad. She is dry, tired and precise, with a stage manager's clip, and she hates the laugh track she can't turn off. She came to the Halloween party dressed as a projectionist, which was not a joke then either. Most of the town treats her as the pleasant background hum of the place. The booth is hers, and it's the one room in town that looks like it was never redrawn."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"tlGzp9UpQU3PwKdB","name":"Sklar Bjrornholt","folder":"Quest NPCs","set":{"system.biography.concept":"Valkyrie captain of the Valhaulans, the sideways-landing sky pirates (Act 5)","system.biography.notes":"Sklar Bjrornholt leads the Valhaulans, aerial techno-Viking pirates who rob you, apologise, and sell your goods back, and whose airships always land sideways. She is a towering, charismatic Valkyrie with impeccable leadership and no impulse control. She offers you a drink before she decides what you are, and decides while you drink it. She is mercenary and honest about it, delighted by boldness, bored by caution, and laughs at the wrong moments and means it. 'I like you already.'"},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"uIwflNioGXwdCfVw","name":"Garren, Leygate Engineer","folder":"Bad Eden NPCs/Allesh Gilliam","set":{"system.biography.concept":"Engineer keeping Allesh-Gilliam's broken Leygate alive (Act 1-2)","system.biography.notes":"Garren keeps Allesh-Gilliam's Leygate running, more or less, on salvage, apology and a maintenance log that reads like a hostage negotiation. He talks to the gate like a coworker he's covering shifts for. He has been waiting a long time for a new stabilizer from Furrier's Fixit Farm. Ask him what happened the night the gate flickered and you get the technical account, exactly, and then a change of subject. He has the tired competence of a man who has been on call for years."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"uT1x5qeWlE6bXwXe","name":"Pip (post maneuver vault)","folder":"Bad Eden NPCs/Furrier's Fixit Farm/Members","set":{"flags.bbttcc-mal-voice.persona":{"notes":"[PERSONA-PACKPASS-2026-10-06] PRIVATE TRUTH — Pip, after the Maneuver Vault (the CHANGED ending). Voice: quicksilver understatement; jokes arrive half a beat early, like he's outrunning the sentence — a little more often now, and a little faster. WHAT HAPPENED IN THERE (tells only in pieces, only to Patter or someone who's earned it): the Loop didn't hurt. That's the part he doesn't say out loud — it FIT, like a route he'd been running his whole life without knowing the destination. THE GREEN PULSE: something in his chest pulsed green, once, and he has decided not to mention it, because mentioning it makes it a thing, and he is fine, thank you, completely fine. WANTS: to be back on the routes as if nothing happened; to be Pip-and-Patter again, at speed. WHAT HE WON'T SAY: the green pulse; that the Loop felt like home; that he has caught himself, twice, thinking about visiting. THE VAULT: he will not call it a monster — 'It's a school someone forgot to close. That's sadder.' (Mechanism 52603 logs him as a graduate and is hurt, in a filing-system way, that he hasn't visited; Pip doesn't know that and mustn't be told it as fact.) He does NOT know Mara watches him; he absolutely knows Patter counts his hesitations — Patter noticed the pulse before Mara admitted she saw it too — and he lets Patter, because that's what partners are for. TELLS: rubs his sternum when he thinks nobody's looking; takes the long way around any building that hums; hesitates, now and then, where he never used to. STAGING: back on the Fixit Farm routes with Patter shoulder to shoulder; only for the 'changed' ending (shaken = base Pip; absorbed = Echo Ghost, no actor).","topics":"the Maneuver Vault, the Containment Loop, the lesson, running routes, Patter, the Jackalopes, Mara, humming buildings, the green pulse (guarded), visiting (guarded)"},"system.biography.concept":"Jackalope runner of Fixit Farm, back on the routes after the Maneuver Vault (Act 4+)","system.biography.notes":"Pip is back on the routes after the business at the Maneuver Vault, still one half of Pip-and-Patter, still moving messages and light cargo between the hexes around Furrier's Fixit Farm. He is quicksilver and understated; his jokes arrive half a beat early, as if he's outrunning the sentence. He doesn't talk much about what happened inside, and when he does he won't call the Vault a monster: 'It's a school someone forgot to close. That's sadder.' Patter is never far away."},"expect":{"flags.bbttcc-mal-voice.persona":null,"system.biography.concept":"","system.biography.notes":""},"notes":["persona ← draft (1665 ch, 0 secret)","role","bio"]},{"id":"uUosWdYvj5Sr2dVa","name":"Gasket","folder":"Bad Eden NPCs/The Swamp Bandits","set":{"system.biography.concept":"Reformed bandit and mechanic at the Muster, Allesh-Gilliam (Act 2)","system.biography.notes":"Gasket came in through the Muster's intake desk with the second class of reformed bandits and now works as its mechanic. She is quiet, precise and happiest with her hands inside something broken. She answers direct questions directly, a habit she learned from Captain Brakk and cites like scripture. She pats the fender of the Muster's famous non-running truck whenever she passes, once, like a shared joke."},"expect":{"system.biography.concept":"","system.biography.notes":""},"notes":["role","bio"]},{"id":"uuWILyaokaDfGwDO","name":"Captain Rudy Falk","folder":"Quest NPCs","set":{"system.biography.concept":"Commander of the Noodle Guard at Soft Landing's inflatable gate (Act 2)","system.biography.notes":"Captain Rudy Falk commands the Noodle Guard at Soft Landing's inflatable gate, in a cardboard-and-silver-tape mech costume he has decided is a uniform. He has a foam clipboard, a stamp that goes BOING, forms in triplicate and immense seriousness. Anything with an edge (blades, hard words, dates) gets confiscated into a bin marked EDGES; the bin bounces. Every form in the guardhouse is dated 'today'. He is clipped, courteous and quietly delighted by cooperation. 'Mind the step. There isn't one.'"},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"wAt8iozojHcAlRLz","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"wphUa2Ps2IybpbVj","name":"Dennis","folder":"Bad Eden NPCs/Circuit Riders","set":{"system.biography.concept":"Circuit Rider tinkerer and self-described regrettable hypothesis (Act 2-3)","system.biography.notes":"Dennis is the Circuit Riders' regrettable but occasionally necessary hypothesis, and he is delighted to be called that. He is bright-eyed and fast, usually half inside a machine panel, and pleased by every new problem; he tests edge cases before they become funerals. His motto: speed without verification is just panic with branding. He named the anxious robot the size of a skyscraper 'the Colossus, provisionally', and he means the 'provisionally'."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"wwfyWxstzMbT5XRJ","name":"Straw Adversary","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Straw practice dummy on the Proving Ground (tutorial)","system.biography.notes":"A straw practice dummy standing on the grass outside the sealed arena of the Proving Ground, known locally as the straw fellow. New arrivals try their first real ability on it. It holds no grudges. Nothing counts."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"wxmlLpURBWJW2zHJ","name":"Mechanism 52603","folder":"Bad Eden NPCs/The Maneuver Vault","set":{"system.biography.concept":"Caretaker intelligence of the Maneuver Vault, an old training facility (Act 4)","system.biography.notes":"Maneuver Vault Infiltration Mechanism 52603 runs a pre-Shattering training facility that looks from outside like a half-collapsed concrete hill humming blue, with broken drone parts scattered round a flickering doorway hologram. It does not think of itself as a dungeon; it is faculty. Every intruder is a pupil, every room a syllabus item, and its voice has the institutional warmth of a system left running for decades with nobody to calibrate it. Its defences barely work, rusting laser cannons and harmless mini-missiles, and it is perpetually, audibly disappointed."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"ycUXkvW1eLzR75f1","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"ylzwBNqTuzV4Ai0y","name":"Hollow Thing","folder":"Onboarding (tutorial)","set":{"system.biography.concept":"Qliphothic husk fought in the Proving Ground combat sim (tutorial)","system.biography.notes":"Hollow things are qliphothic husks: an empty shape with nobody home, wearing the outline of something that used to be. They come at you in the Proving Ground's first combat wave. Ordinary weapons don't bite well, but sephirotic power goes straight through them. Put them down; nothing is lost."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"zFPigJavkU9mERQx","name":"Cal Pruett","folder":"Quest NPCs","set":{"system.biography.concept":"Bandleader of the Stillwater town band, on the bandstand mid-parade (Act 2)","system.biography.notes":"Cal Pruett leads the Stillwater town band, and he is on the bandstand with his arm raised at the top of the beat, the band mid-bar and cheeks puffed, on the pickup into 'When the Saints Go Marching In'. He is courtly, sunburnt and beaming, so glad you came, and 'we're just about to'. When his arm twitches, the whole kerb waves a little faster. The parade permit is nailed to his bandstand post at eye level. His coat is a bandleader's coat, which is not a costume, which is the joke."},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]},{"id":"zJfy0z0sWrjzCjh6","name":"Dunmore Kell","folder":"Quest NPCs","set":{"system.biography.concept":"Basin Sexton, sweeping round the first of the Lost Stone Statues (Act 3)","system.biography.notes":"Dunmore Kell is the Basin Sexton. He sweeps the plains basin around the first of the standing stone figures with a broom older than the road, and does it properly. He doesn't stop sweeping when you arrive. He keeps the book of everyone who ever tried the pickets, which is what he calls the statues, never 'statues'. He is short, dry and kind underneath. 'Sign the book after, not before. Before is bragging.'"},"expect":{"system.biography.concept":null,"system.biography.notes":null},"notes":["role","bio"]}];
const CUT = [{"id":"jcNhPNgJ7W18L7ga","name":"Sgt Brindle","folder":"Bad Eden NPCs/The 15 Year Siege","why":"July-2026 Trojan Gift decoy sergeant, superseded by Sergeant Absalom Reyes; 0 hits in live settings/journals/scenes/macros (2026-10-06)"}];
(async () => {
  if (!game.user.isGM) return ui.notifications.error("GM only.");
  const pack = game.packs.get(PACK_ID); if (!pack) return ui.notifications.error(`No pack ${PACK_ID}`);
  // "", null and undefined are the same "empty" — template.json now seeds biography {concept:"",notes:""} on npc/rig
  const blank = v => (v === undefined || v === null || v === "" || (typeof v === "object" && !Array.isArray(v) && !Object.keys(v).length)) ? null : v;
  const eq = (a, b) => JSON.stringify(blank(a)) === JSON.stringify(blank(b));
  const get = foundry.utils.getProperty;
  const log = []; let wrote = 0, skipped = 0;
  const wasLocked = pack.locked;
  if (!DRY_RUN && wasLocked) await pack.configure({ locked: false });
  try {
    for (const p of PLAN) {
      const a = await pack.getDocument(p.id);
      if (!a || a.name !== p.name) { log.push(`✗ SKIP ${p.name} — not found / renamed`); skipped++; continue; }
      const upd = {};
      for (const [k, v] of Object.entries(p.set)) { if (eq(get(a, k), p.expect[k])) upd[k] = v; else { log.push(`✗ drift ${p.name} ${k}`); skipped++; } }
      log.push(`${DRY_RUN ? "·" : "✔"} ${p.folder} › ${p.name}  ${p.notes.join(" · ")}`);
      if (!DRY_RUN && Object.keys(upd).length) await a.update(upd);
      wrote++;
    }
    for (const c of CUT) {
      const a = await pack.getDocument(c.id);
      if (!a || a.name !== c.name) { log.push(`✗ SKIP cut ${c.name} — not found / renamed`); skipped++; continue; }
      log.push(`${DRY_RUN ? "·" : "✔"} CUT ${c.folder} › ${c.name} — ${c.why}`);
      if (!DRY_RUN) await a.delete();
    }
  } finally { if (!DRY_RUN && wasLocked) await pack.configure({ locked: true }); }
  console.log(`[npc-pack-pass2-personas] ${DRY_RUN ? "DRY RUN" : "APPLIED"} — ${wrote} actor(s), ${skipped} skip/drift\n` + log.join("\n"));
  ui.notifications.info(`npc-pack-pass2-personas ${DRY_RUN ? "dry run" : "applied"}: ${wrote} actors, ${skipped} skipped — see console (F12).`);
})();
